"""验证报告的基线加载与结构化对比（schema v4）。

``verify --baseline PATH`` 把上次 ``verify`` 生成的 JSON 报告作为基线：
先按原流程执行并生成当前结果（执行顺序、种子、产物目录与字段语义均不
受影响），再把当前报告与基线按 name 对齐逐类对比——测试台比
``status``/``reason``，断言比终态 ``status``/``fail_count``，覆盖率比
``status``/``hits``/``hit_testbenches``。

每条差异固定为 ``kind``、``name``、``expected``、``actual`` 四个字段：

- 基线缺失（基线有、当前无）：``expected`` 为基线完整记录，
  ``actual`` 为 ``None``；
- 当前新增（基线无、当前有）：``expected`` 为 ``None``，``actual``
  为当前完整记录；
- 字段差异：``expected``/``actual`` 为对应标量。

差异按类别（testbench、assertion、coverage）顺序排列，类别内按 name
的 Unicode 码点排序；同名的多个字段差异分别保留，不合并。
"""

import json
import os

from .errors import InputError
from .report import (
    VERIFICATION_COMPARISON_SCHEMA_VERSION,
    VERIFICATION_FORMAT,
    VERIFICATION_SCHEMA_VERSION,
    sanitize_path,
)

#: 可作为基线读取的报告版本（v3 原始报告与 v4 带对比报告均可）。
SUPPORTED_BASELINE_SCHEMA_VERSIONS = (
    VERIFICATION_SCHEMA_VERSION,
    VERIFICATION_COMPARISON_SCHEMA_VERSION,
)

#: 各类别参与对比的字段；顺序即同名多个字段差异的稳定排列顺序。
_COMPARE_FIELDS = {
    "testbench": ("status", "reason"),
    "assertion": ("status", "fail_count"),
    "coverage": ("status", "hits", "hit_testbenches"),
}

#: 对比类别在 ``mismatches`` 中的排列顺序（映射到报告数组字段名）。
_CATEGORIES = (
    ("testbench", "testbenches"),
    ("assertion", "assertions"),
    ("coverage", "coverage"),
)


def load_baseline_report(path):
    """读取并校验基线报告，返回报告 dict。

    :raises InputError: 基线不存在、不可读、非合法 JSON、不是 rtl-lab
        验证报告或版本不受支持；这些情况不生成或覆盖任何报告。
    """
    if not isinstance(path, str) or not path.strip():
        raise InputError("基线报告路径不能为空")
    if not os.path.isfile(path):
        raise InputError(f"基线报告不存在：{path}")
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as exc:
        raise InputError(f"基线报告不是合法 JSON：{path}") from exc
    except (OSError, UnicodeDecodeError) as exc:
        raise InputError(f"基线报告不可读：{path}") from exc
    if not isinstance(data, dict) or data.get("format") != VERIFICATION_FORMAT:
        raise InputError(f"基线不是 rtl-lab 验证报告：{path}")
    if data.get("schema_version") not in SUPPORTED_BASELINE_SCHEMA_VERSIONS:
        raise InputError(
            f"基线报告版本不受支持：{path}"
            f"（schema_version={data.get('schema_version')!r}）"
        )
    return data


def _compare_category(category, baseline_entries, current_entries):
    """按 name 对齐对比一个类别，返回该类别的差异列表（按 name 码点排序）。"""
    fields = _COMPARE_FIELDS[category]
    base_by_name = {e["name"]: e for e in baseline_entries}
    curr_by_name = {e["name"]: e for e in current_entries}
    diffs = []
    for name in sorted(set(base_by_name) | set(curr_by_name)):
        expected = base_by_name.get(name)
        actual = curr_by_name.get(name)
        if expected is None:
            diffs.append({
                "kind": f"{category}_added",
                "name": name,
                "expected": None,
                "actual": actual,
            })
        elif actual is None:
            diffs.append({
                "kind": f"{category}_missing",
                "name": name,
                "expected": expected,
                "actual": None,
            })
        else:
            for field in fields:
                if expected.get(field) != actual.get(field):
                    diffs.append({
                        "kind": f"{category}_{field}",
                        "name": name,
                        "expected": expected.get(field),
                        "actual": actual.get(field),
                    })
    return diffs


def compare_verification_reports(current, baseline, *, baseline_path, workdir):
    """对比当前报告与基线报告，返回报告的 ``comparison`` 字段值。

    ``baseline`` 为脱敏后的基线路径；``passed`` 为无差异标记；
    ``mismatches`` 为结构化差异列表（无差异时为空）。
    """
    mismatches = []
    for category, key in _CATEGORIES:
        mismatches.extend(_compare_category(
            category, baseline.get(key) or [], current.get(key) or [],
        ))
    return {
        "baseline": sanitize_path(baseline_path, workdir),
        "passed": not mismatches,
        "mismatches": mismatches,
    }

"""统一验证报告（schema v3）构建与聚合单测（不调用仿真器）。"""

import pytest

from rtl_lab.report import (
    TB_STATUSES,
    VERIFICATION_FORMAT,
    VERIFICATION_SCHEMA_VERSION,
    build_verification_report,
    ensure_report_writable,
)

def _outcome(name, *, status="passed", reason="passed", required=True,
             top=None, testbench_file=None, assertions=None, coverage=None,
             start="2026-01-01T00:00:00+00:00",
             end="2026-01-01T00:00:01+00:00",
             compile_argv=("/usr/bin/iverilog", "-o", "/w/sim.vvp", "/w/d.v"),
             simulate_argv=("/usr/bin/vvp", "sim.vvp", "+SEED=0")):
    return {
        "name": name,
        "top": top or name,
        "testbench_file": testbench_file or f"/w/tb/{name}.v",
        "status": status,
        "reason": reason,
        "required": required,
        "start_time": start,
        "end_time": end,
        "diagnostics": [],
        "assertions": assertions if assertions is not None else {
            "a1": {"status": "passed", "fail_count": 0}
        },
        "coverage": coverage if coverage is not None else {"c1": 1},
        "commands": {
            "compile": list(compile_argv),
            "simulate": list(simulate_argv),
        },
    }


def _build(outcomes, *, threshold=1.0, points=None, run_id="rid",
           sources=("/w/d.v",), tb_files=None):
    if tb_files is None:
        tb_files = [o["testbench_file"] for o in outcomes]
    return build_verification_report(
        run_id=run_id,
        sources=list(sources),
        testbench_files=tb_files,
        coverage_config={"threshold": threshold, "points": points or []},
        duration="100ns",
        compile_command=(
            outcomes[0]["commands"]["compile"] if outcomes else []
        ),
        simulate_command=(
            outcomes[0]["commands"]["simulate"] if outcomes else []
        ),
        outcomes=outcomes,
        generated_at="2026-01-01T00:00:02+00:00",
        workdir="/w",
        known_paths=(),
    )


def test_shape_and_version_markers():
    data, result = _build([_outcome("t1")])
    assert data["schema_version"] == VERIFICATION_SCHEMA_VERSION
    assert data["format"] == VERIFICATION_FORMAT
    assert list(data.keys()) == [
        "schema_version", "format", "run_id", "result", "generated_at",
        "tool", "config", "compilation", "testbenches", "testbench_summary",
        "assertion_summary", "assertions", "coverage_summary", "coverage",
        "skipped_required",
    ]
    assert result == "passed"
    assert data["run_id"] == "rid"
    assert data["result"] == "passed"
    assert data["generated_at"] == "2026-01-01T00:00:02+00:00"
    tb = data["testbenches"][0]
    assert list(tb.keys()) == [
        "name", "top", "testbench", "status", "reason", "required",
        "start_time", "end_time", "command", "diagnostics", "assertions",
        "coverage",
    ]
    assert tb["testbench"] == "tb/t1.v"


def test_compilation_records_actual_compiled_sources_order():
    data, _ = _build(
        [_outcome("t1")], sources=("/w/src/z.v", "/w/src/a.v")
    )
    assert data["compilation"]["sources"] == ["src/z.v", "src/a.v"]


def test_config_summary_fields():
    data, _ = _build([_outcome("t1")])
    assert data["config"]["duration"] == "100ns"
    assert data["config"]["coverage"] == {"threshold": 1.0, "points": []}
    # 顶层代表性命令已脱敏。
    assert data["config"]["compile"][0] == "iverilog"
    assert data["config"]["simulate"][0] == "vvp"


def test_counts_all_pass():
    data, result = _build([
        _outcome("t1", assertions={
            "a": {"status": "passed", "fail_count": 0},
            "b": {"status": "passed", "fail_count": 0},
        }, coverage={"c1": 1, "c2": 3}),
        _outcome("t2", assertions={
            "a": {"status": "passed", "fail_count": 0},
        }, coverage={"c1": 2}),
    ])
    assert result == "passed"
    assert data["testbench_summary"] == {
        "passed": 2, "failed": 0, "skipped": 0
    }
    # 断言按首次出现顺序合并，fail_count 跨台求和。
    assert [a["name"] for a in data["assertions"]] == ["a", "b"]
    assert data["assertion_summary"] == {
        "total": 2, "passed": 2, "failed": 0, "fail_count": 0
    }
    # 覆盖率点按首次出现顺序：c1 在 t1/t2 均命中，c2 仅 t1。
    assert [c["name"] for c in data["coverage"]] == ["c1", "c2"]
    by = {c["name"]: c for c in data["coverage"]}
    assert by["c1"] == {
        "name": "c1", "status": "hit", "hits": 3, "hit_testbenches": 2
    }
    assert by["c2"] == {
        "name": "c2", "status": "hit", "hits": 3, "hit_testbenches": 1
    }
    summary = data["coverage_summary"]
    assert summary["total_points"] == 2
    assert summary["hit_points"] == 2
    assert summary["ratio"] == 1.0
    assert summary["met"] is True
    assert summary["unavailable_points"] == []


def test_single_testbench_failure_makes_failed():
    data, result = _build([
        _outcome("t1"),
        _outcome("t2", status="failed", reason="simulation_failed",
                 assertions={}, coverage={}),
    ])
    assert result == "failed"
    assert data["result"] == "failed"
    assert data["testbench_summary"] == {
        "passed": 1, "failed": 1, "skipped": 0
    }
    assert [t["name"] for t in data["testbenches"]] == ["t1", "t2"]


def test_assertion_failure_aggregation_and_fail_count():
    data, result = _build([
        _outcome("t1", assertions={
            "x": {"status": "failed", "fail_count": 2},
        }, coverage={"c1": 1}),
        _outcome("t2", assertions={
            "x": {"status": "passed", "fail_count": 0},
        }, coverage={"c1": 1}),
    ])
    assert result == "failed"
    assert data["assertions"] == [
        {"name": "x", "status": "failed", "fail_count": 2}
    ]
    assert data["assertion_summary"]["failed"] == 1
    assert data["assertion_summary"]["fail_count"] == 2


def test_skipped_optional_does_not_fail_conclusion():
    data, result = _build([
        _outcome("t1"),
        _outcome("t2", status="skipped", reason="skipped", required=False,
                 assertions={}, coverage={}),
    ])
    assert result == "passed"
    assert data["testbench_summary"] == {
        "passed": 1, "failed": 0, "skipped": 1
    }
    assert data["skipped_required"] == []


def test_skipped_required_fails_conclusion():
    data, result = _build([
        _outcome("t1"),
        _outcome("t2", status="skipped", reason="skipped", required=True,
                 assertions={}, coverage={}),
    ])
    assert result == "failed"
    assert data["skipped_required"] == ["t2"]


def test_coverage_below_threshold_fails():
    data, result = _build(
        [_outcome("t1", coverage={"c1": 1, "c2": 0})],
        threshold=0.6,
    )
    # 2 个点，命中 1 个 => ratio 0.5 < 0.6 => failed。
    assert data["coverage_summary"]["ratio"] == 0.5
    assert result == "failed"
    assert data["coverage_summary"]["met"] is False


def test_coverage_threshold_boundary_inclusive():
    data, result = _build(
        [_outcome("t1", coverage={"c1": 1, "c2": 0})], threshold=0.5,
    )
    assert data["coverage_summary"]["ratio"] == 0.5
    assert result == "passed"
    assert data["coverage_summary"]["met"] is True


def test_missed_point_has_zero_hits():
    data, _ = _build([_outcome("t1", coverage={"c1": 1, "c2": 0})])
    by = {c["name"]: c for c in data["coverage"]}
    assert by["c2"]["status"] == "missed"
    assert by["c2"]["hits"] == 0
    assert by["c2"]["hit_testbenches"] == 0


def test_configured_point_without_stats_is_unavailable_counts_in_denom():
    data, result = _build(
        [_outcome("t1", coverage={"c1": 1})],
        threshold=1.0, points=["c1", "missing"],
    )
    by = {c["name"]: c for c in data["coverage"]}
    assert by["missing"] == {
        "name": "missing", "status": "unavailable",
        "hits": None, "hit_testbenches": None,
    }
    assert data["coverage_summary"]["total_points"] == 2
    assert data["coverage_summary"]["hit_points"] == 1
    assert data["coverage_summary"]["ratio"] == 0.5
    assert data["coverage_summary"]["unavailable_points"] == ["missing"]
    assert result == "failed"


def test_order_stable_independent_of_dict_iteration(tmp_path):
    # 以不同插入顺序构建，断言报告数组顺序只取决于测试台选择顺序。
    o1 = _outcome("beta", assertions={
        "z": {"status": "passed", "fail_count": 0},
        "a": {"status": "passed", "fail_count": 0},
    }, coverage={"zz": 1, "aa": 1})
    o2 = _outcome("alpha", assertions={
        "m": {"status": "passed", "fail_count": 0},
    }, coverage={"mm": 1})
    data, _ = _build([o1, o2])
    assert [t["name"] for t in data["testbenches"]] == ["beta", "alpha"]
    assert [a["name"] for a in data["assertions"]] == ["z", "a", "m"]
    assert [c["name"] for c in data["coverage"]] == ["zz", "aa", "mm"]


def test_diagnostics_sanitized():
    o = _outcome("t1")
    o["diagnostics"] = ["see /tmp/secret/x.v and /w/d.v"]
    data, _ = _build([o])
    blob = data["testbenches"][0]["diagnostics"][0]
    assert "/tmp/secret" not in blob and "x.v" in blob
    assert "/w/d.v" not in blob and "d.v" in blob


def test_duplicate_tb_name_raises():
    with pytest.raises(RuntimeError):
        _build([_outcome("same"), _outcome("same")])


def test_empty_outcomes_raises():
    with pytest.raises(RuntimeError):
        _build([])


def test_zero_coverage_points_is_failed_at_builder_without_raising():
    # 构建器本身不裁决“运行是否必须有覆盖率”（该运行级规则在 verify 中）；
    # 零点时 ratio 为 None、met 为 False，结论 failed。
    data, result = _build([_outcome("t1", coverage={})])
    assert data["coverage_summary"]["total_points"] == 0
    assert data["coverage_summary"]["ratio"] is None
    assert data["coverage_summary"]["met"] is False
    assert result == "failed"


def test_illegal_status_raises():
    o = _outcome("t1")
    o["status"] = "weird"
    with pytest.raises(RuntimeError):
        _build([o])


def test_status_enum_domain():
    assert TB_STATUSES == ("passed", "failed", "skipped")


def test_ensure_report_writable_existing_file_ok(tmp_path):
    f = tmp_path / "r.json"
    f.write_text("{}")
    ensure_report_writable(str(f))  # 不抛异常即通过


def test_ensure_report_writable_directory_rejected(tmp_path):
    with pytest.raises(OSError):
        ensure_report_writable(str(tmp_path))


def test_ensure_report_writable_nonexistent_under_existing_dir(tmp_path):
    target = str(tmp_path / "nested" / "r.json")
    ensure_report_writable(target)  # 最近存在祖先可写即通过


def test_ensure_report_writable_creates_nothing(tmp_path):
    target = tmp_path / "r.json"
    ensure_report_writable(str(target))
    assert not target.exists()  # 校验本身不落盘

"""解析测试台标准输出中的单行结果。

支持三类记录（均为单行，名称为去除首尾空白后非空的单个 token）：

- ``ASSERT PASS name``
- ``ASSERT FAIL name message``（message 为 name 之后的全部文本，可为空）
- ``COVER name``

断言状态取最后一次结果；失败次数按 FAIL 记录累加；
覆盖率点按命中次数累加。所有映射均按名称首次出现的顺序保存。
"""

import re

#: 三类记录的标记前缀。
ASSERT_PREFIX = "ASSERT PASS "
ASSERT_FAIL_PREFIX = "ASSERT FAIL "
COVER_PREFIX = "COVER "

#: 名称为首个非空白 token；FAIL 的 message 为名称之后的全部文本。
_PASS_RE = re.compile(r"^ASSERT\s+PASS\s+(\S+)\s*$")
_FAIL_RE = re.compile(r"^ASSERT\s+FAIL\s+(\S+)(?:\s+(.*?))?\s*$")
_COVER_RE = re.compile(r"^COVER\s+(\S+)\s*$")


class ResultCollector:
    """按行收集断言与覆盖率结果。"""

    def __init__(self):
        #: name -> {"status": "passed"/"failed", "fail_count": int}
        self.assertions = {}
        #: name -> 命中次数
        self.coverage = {}

    def feed_line(self, line):
        """处理一行（不含行尾换行）。无法识别的行将被忽略。

        标记与名称之间允许任意空白（空格或制表符）。

        :returns: 识别出的记录元组（仅供调试），未识别返回 None。
        """
        fail = _FAIL_RE.match(line)
        if fail:
            name = fail.group(1)
            message = fail.group(2) or ""
            entry = self.assertions.setdefault(
                name, {"status": "failed", "fail_count": 0}
            )
            entry["status"] = "failed"
            entry["fail_count"] += 1
            return ("assert_fail", name, message)

        pas = _PASS_RE.match(line)
        if pas:
            name = pas.group(1)
            entry = self.assertions.setdefault(
                name, {"status": "passed", "fail_count": 0}
            )
            entry["status"] = "passed"
            return ("assert_pass", name)

        cov = _COVER_RE.match(line)
        if cov:
            name = cov.group(1)
            self.coverage[name] = self.coverage.get(name, 0) + 1
            return ("cover", name)

        return None

    def feed_text(self, text):
        """处理整段文本，按 \\n / \\r\\n 分行。"""
        for raw in text.splitlines():
            self.feed_line(raw)

    @property
    def has_failure(self):
        """是否出现过且最终仍处于失败状态的断言。"""
        return any(a["status"] == "failed" for a in self.assertions.values())

"""基线加载与结构化对比单测（不调用仿真器）。"""

import json

import pytest

from rtl_lab.baseline import (
    compare_verification_reports,
    load_baseline_report,
)
from rtl_lab.errors import InputError


def _tb(name, *, status="passed", reason="passed"):
    return {
        "name": name,
        "top": name,
        "testbench": f"tb/{name}.v",
        "status": status,
        "reason": reason,
        "required": True,
        "start_time": "2026-01-01T00:00:00+00:00",
        "end_time": "2026-01-01T00:00:01+00:00",
        "command": {"compile": ["iverilog"], "simulate": ["vvp"]},
        "diagnostics": [],
        "assertions": [],
        "coverage": [],
    }


def _report(*, testbenches=(), assertions=(), coverage=()):
    return {
        "schema_version": 3,
        "format": "rtl-lab-verification",
        "run_id": "rid",
        "result": "passed",
        "testbenches": list(testbenches),
        "assertions": list(assertions),
        "coverage": list(coverage),
    }


def _compare(current, baseline, baseline_path="/w/base.json", workdir="/w"):
    return compare_verification_reports(
        current, baseline, baseline_path=baseline_path, workdir=workdir
    )


# ---- load_baseline_report ----


def test_load_baseline_ok_v3(tmp_path):
    f = tmp_path / "base.json"
    f.write_text(json.dumps(_report()), encoding="utf-8")
    data = load_baseline_report(str(f))
    assert data["format"] == "rtl-lab-verification"


def test_load_baseline_ok_v4(tmp_path):
    report = _report()
    report["schema_version"] = 4
    report["comparison"] = {
        "baseline": "older.json", "passed": True, "mismatches": [],
    }
    f = tmp_path / "base.json"
    f.write_text(json.dumps(report), encoding="utf-8")
    assert load_baseline_report(str(f))["schema_version"] == 4


def test_load_baseline_missing_file(tmp_path):
    with pytest.raises(InputError):
        load_baseline_report(str(tmp_path / "nope.json"))


def test_load_baseline_directory_rejected(tmp_path):
    with pytest.raises(InputError):
        load_baseline_report(str(tmp_path))


def test_load_baseline_invalid_json(tmp_path):
    f = tmp_path / "base.json"
    f.write_text("{not json", encoding="utf-8")
    with pytest.raises(InputError):
        load_baseline_report(str(f))


def test_load_baseline_not_verification_report(tmp_path):
    f = tmp_path / "base.json"
    # schema v1 单次运行报告：没有 format 标识。
    f.write_text(json.dumps({"schema_version": 1, "tool": "x"}),
                 encoding="utf-8")
    with pytest.raises(InputError):
        load_baseline_report(str(f))


def test_load_baseline_non_dict_json(tmp_path):
    f = tmp_path / "base.json"
    f.write_text("[1, 2, 3]", encoding="utf-8")
    with pytest.raises(InputError):
        load_baseline_report(str(f))


def test_load_baseline_unsupported_version(tmp_path):
    report = _report()
    report["schema_version"] = 5
    f = tmp_path / "base.json"
    f.write_text(json.dumps(report), encoding="utf-8")
    with pytest.raises(InputError):
        load_baseline_report(str(f))


# ---- compare_verification_reports ----


def test_compare_identical_reports_pass():
    current = _report(
        testbenches=[_tb("t1")],
        assertions=[{"name": "a1", "status": "passed", "fail_count": 0}],
        coverage=[{
